import { cn } from "@/lib/utils";
import { ConfidenceBadge } from "@/components/ui/confidence-badge";
import { AcceptRejectButtons } from "@/components/ui/accept-reject-buttons";

interface TagsSuggestionRowProps {
  tags: string[];
  confidence?: "high" | "medium" | "low";
  summary?: string;
  readOnly?: boolean;
  onApply?: (tags: string[]) => void;
  onReject?: () => void;
  className?: string;
}

export function TagsSuggestionRow({
  tags,
  confidence,
  summary,
  readOnly = false,
  onApply,
  onReject,
  className,
}: TagsSuggestionRowProps) {
  return (
    <div
      className={cn("flex items-start gap-2 rounded-md border p-2 text-sm", className)}
      data-readonly={readOnly}
    >
      <div className="min-w-0 flex-1">
        <div className="flex flex-wrap gap-1">
          {tags.map((tag) => (
            <span
              key={tag}
              className="inline-flex items-center rounded-full bg-stone-100 px-2 py-0.5 text-xs text-stone-700"
            >
              {tag}
            </span>
          ))}
        </div>
        {summary && <p className="mt-1 text-xs text-stone-500">{summary}</p>}
      </div>
      {confidence && <ConfidenceBadge confidence={confidence} />}
      {!readOnly && onApply && onReject && (
        <AcceptRejectButtons onAccept={() => onApply(tags)} onReject={onReject} />
      )}
    </div>
  );
}
